#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Expand the nine original ZEN-1 patches into const flash voices.

The device avoids a mutable expanded-patch buffer and each sounding voice can
retain its patch across preset changes. No sound settings are changed.

Run: python3 app/vendor/zen_fm/gen_factory.py app/fm_port/fm_factory.h
"""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from zen_patches import PATCHES


def main(path):
    out = [
        "/* SPDX-License-Identifier: GPL-3.0-only */",
        "/* Generated by app/vendor/zen_fm/gen_factory.py from the original ZEN-1",
        " * patch settings. Expanded DX7-format voices, OP6 first, name + NUL. */",
        "#pragma once", "#include <stdint.h>",
        "static const uint8_t FM_FACTORY[9][156] = {",
    ]
    for name, voice in PATCHES:
        out.append("    { /* " + name + " */")
        vals = list(voice) + [0]
        for i in range(0, len(vals), 16):
            out.append("        " + ", ".join(str(x) for x in vals[i:i+16]) + ",")
        out.append("    },")
    out.extend(["};", ""])
    Path(path).write_text("\n".join(out))


if __name__ == "__main__":
    main(sys.argv[1])
